# Step 1-4: Calculate the average mean temperature for each zip code and filter for those above 60.
# Then, select only the zip_code from this filtered collection to create a set of qualifying zip codes.
qualifying_zip_codes_data = bike_1.weathers.PARTITION(
    name="zip_weather_data_groups",
    by=zip_code # Group by zip_code (int64)
).CALCULATE(
    zip_code_area=zip_code, # Retain the zip_code from the partition key (int64)
    avg_mean_temp=AVG(weathers.mean_temperature_f) # Calculate average temperature for each zip code group
).WHERE(
    avg_mean_temp > 60 # Filter for zip codes with average temperature above 60
).CALCULATE(
    # Select only the qualifying zip_code values. No casting needed as both zip_code columns are int64.
    zip_code_val=zip_code_area
)

# Step 5-6: Filter trips based on the qualifying zip codes and select their IDs.
result = bike_1.trips.WHERE(
    ISIN(zip_code, qualifying_zip_codes_data.zip_code_val)
).CALCULATE(
    trip_id=id
)

