result = GRAPH.CALCULATE(
    count_of_states=COUNT(
        colleges.PARTITION(name="state_group", by=state).CALCULATE(
            state_name=state,
            # Check if this state has any 'mid' tryouts (removed 'decision == Accepted')
            has_mid_players=HAS(
                colleges.tryouts.WHERE(
                    (tryouts.ppos == 'mid')
                )
            ) == 1,
            # Check if this state has any 'goalie' tryouts (removed 'decision == Accepted')
            has_goalie_players=HAS(
                colleges.tryouts.WHERE(
                    (tryouts.ppos == 'goalie')
                )
            ) == 1
        ).WHERE(
            # Filter for states that have 'mid' players AND do NOT have 'goalie' players
            (state_group.has_mid_players == 1) & (state_group.has_goalie_players == 0)
        )
    )
)

