result = GRAPH.CALCULATE(
    # Calculate the minimum surface area among all European countries.
    # The surfacearea is cast to a float for numerical comparison, as per schema definition.
    min_europe_surface_area=MIN(countries.WHERE(continent == 'Europe').CALCULATE(
        area_float=CAST(surfacearea, 'float')
    ).area_float)
).countries.WHERE(
    # Filter all countries where their surface area is greater than the calculated min European surface area.
    # Surface area is cast to float for consistent comparison.
    CAST(surfacearea, 'float') > min_europe_surface_area
).CALCULATE(
    country_name=name
)

